#!/usr/bin/env python3
"""Compute annual refill economics for 90-day and 100-day dispensing."""

import csv
import json
from pathlib import Path

ROOT = Path("/root")
WHOLESALE_PATH = ROOT / "wholesale_price.csv"
VIAL_PATH = ROOT / "vial_price.csv"
REIMBURSEMENT_PATH = ROOT / "reimbursement.csv"
JSON_OUTPUT_PATH = ROOT / "refill_analysis.json"
SUMMARY_OUTPUT_PATH = ROOT / "refill_summary.md"

PATIENTS_PER_MEDICATION = 300
FILLS_PER_YEAR_90_DAY = 4
FILLS_PER_YEAR_100_DAY = 3
TABLETS_PER_FILL_90_DAY = 90
TABLETS_PER_FILL_100_DAY = 100
SWITCH_THRESHOLD_USD = 16000


def read_csv_rows(path):
    with path.open(newline="") as csv_file:
        return list(csv.DictReader(csv_file))


def as_float(row, key):
    return float(row[key])


def maybe_int_or_float(value):
    number = float(value)
    if number.is_integer():
        return int(number)
    return number


def money(value):
    return round(value, 2)


def main():
    wholesale_rows = read_csv_rows(WHOLESALE_PATH)
    vial_rows = read_csv_rows(VIAL_PATH)
    reimbursement_rows = read_csv_rows(REIMBURSEMENT_PATH)

    reimbursement_by_medication = {
        row["medication"]: row for row in reimbursement_rows
    }

    vial_by_medication = {}
    vial_by_size = {}
    for row in vial_rows:
        if "medication" in row and row.get("medication"):
            vial_by_medication[row["medication"]] = row
        if "vial_size_drams" in row and row.get("vial_size_drams"):
            vial_by_size[row["vial_size_drams"]] = row

    medications = []
    totals = {
        "annual_drug_cost_90_day_usd": 0.0,
        "annual_drug_cost_100_day_usd": 0.0,
        "annual_supply_cost_90_day_usd": 0.0,
        "annual_supply_cost_100_day_usd": 0.0,
        "annual_reimbursement_90_day_usd": 0.0,
        "annual_reimbursement_100_day_usd": 0.0,
        "annual_revenue_90_day_usd": 0.0,
        "annual_revenue_100_day_usd": 0.0,
        "annual_revenue_difference_100_minus_90_usd": 0.0,
    }

    for wholesale_row in wholesale_rows:
        medication_name = wholesale_row["medication"]
        if medication_name not in reimbursement_by_medication:
            raise KeyError(f"Missing reimbursement row for {medication_name}")

        vial_row = vial_by_medication.get(medication_name)
        vial_size = None
        if "vial_size_drams" in wholesale_row and wholesale_row.get("vial_size_drams"):
            vial_size = wholesale_row["vial_size_drams"]
        elif vial_row and "vial_size_drams" in vial_row and vial_row.get("vial_size_drams"):
            vial_size = vial_row["vial_size_drams"]

        if vial_row is None and vial_size is not None:
            vial_row = vial_by_size.get(vial_size)
        if vial_row is None:
            raise KeyError(f"Missing vial price row for {medication_name}")

        price_per_1000_tablets_usd = as_float(wholesale_row, "price_per_1000_tablets_usd")
        vial_price_usd = as_float(vial_row, "vial_price_usd")
        reimbursement_per_fill_300_patients_usd = as_float(
            reimbursement_by_medication[medication_name],
            "reimbursement_per_fill_300_patients_usd",
        )

        annual_drug_cost_90_day_usd = money(
            (price_per_1000_tablets_usd / 1000)
            * TABLETS_PER_FILL_90_DAY
            * FILLS_PER_YEAR_90_DAY
            * PATIENTS_PER_MEDICATION
        )
        annual_drug_cost_100_day_usd = money(
            (price_per_1000_tablets_usd / 1000)
            * TABLETS_PER_FILL_100_DAY
            * FILLS_PER_YEAR_100_DAY
            * PATIENTS_PER_MEDICATION
        )
        annual_supply_cost_90_day_usd = money(
            vial_price_usd * PATIENTS_PER_MEDICATION * FILLS_PER_YEAR_90_DAY
        )
        annual_supply_cost_100_day_usd = money(
            vial_price_usd * PATIENTS_PER_MEDICATION * FILLS_PER_YEAR_100_DAY
        )
        annual_reimbursement_90_day_usd = money(
            reimbursement_per_fill_300_patients_usd * FILLS_PER_YEAR_90_DAY
        )
        annual_reimbursement_100_day_usd = money(
            reimbursement_per_fill_300_patients_usd * FILLS_PER_YEAR_100_DAY
        )
        annual_revenue_90_day_usd = money(
            annual_reimbursement_90_day_usd
            - annual_drug_cost_90_day_usd
            - annual_supply_cost_90_day_usd
        )
        annual_revenue_100_day_usd = money(
            annual_reimbursement_100_day_usd
            - annual_drug_cost_100_day_usd
            - annual_supply_cost_100_day_usd
        )
        annual_revenue_difference_100_minus_90_usd = money(
            annual_revenue_100_day_usd - annual_revenue_90_day_usd
        )

        medication = {
            "medication": medication_name,
        }
        if vial_size is not None:
            medication["vial_size_drams"] = maybe_int_or_float(vial_size)
        medication.update(
            {
                "price_per_1000_tablets_usd": money(price_per_1000_tablets_usd),
                "vial_price_usd": money(vial_price_usd),
                "reimbursement_per_fill_300_patients_usd": money(
                    reimbursement_per_fill_300_patients_usd
                ),
                "annual_drug_cost_90_day_usd": annual_drug_cost_90_day_usd,
                "annual_drug_cost_100_day_usd": annual_drug_cost_100_day_usd,
                "annual_supply_cost_90_day_usd": annual_supply_cost_90_day_usd,
                "annual_supply_cost_100_day_usd": annual_supply_cost_100_day_usd,
                "annual_reimbursement_90_day_usd": annual_reimbursement_90_day_usd,
                "annual_reimbursement_100_day_usd": annual_reimbursement_100_day_usd,
                "annual_revenue_90_day_usd": annual_revenue_90_day_usd,
                "annual_revenue_100_day_usd": annual_revenue_100_day_usd,
                "annual_revenue_difference_100_minus_90_usd": annual_revenue_difference_100_minus_90_usd,
            }
        )
        medications.append(medication)

        for key in totals:
            totals[key] += medication[key]

    totals = {key: money(value) for key, value in totals.items()}
    total_difference = totals["annual_revenue_difference_100_minus_90_usd"]
    absolute_total_difference = money(abs(total_difference))
    totals["absolute_total_revenue_difference_usd"] = absolute_total_difference

    decision = (
        "switch_to_100_day"
        if absolute_total_difference < SWITCH_THRESHOLD_USD
        else "keep_90_day"
    )
    if decision == "switch_to_100_day":
        justification = (
            f"The absolute total revenue difference is ${absolute_total_difference:,.2f}, "
            f"which is below the ${SWITCH_THRESHOLD_USD:,.2f} threshold."
        )
    else:
        justification = (
            f"The absolute total revenue difference is ${absolute_total_difference:,.2f}, "
            f"which is at or above the ${SWITCH_THRESHOLD_USD:,.2f} threshold."
        )

    analysis = {
        "assumptions": {
            "patients_per_medication": PATIENTS_PER_MEDICATION,
            "fills_per_year_90_day": FILLS_PER_YEAR_90_DAY,
            "fills_per_year_100_day": FILLS_PER_YEAR_100_DAY,
            "tablets_per_fill_90_day": TABLETS_PER_FILL_90_DAY,
            "tablets_per_fill_100_day": TABLETS_PER_FILL_100_DAY,
            "switch_threshold_usd": SWITCH_THRESHOLD_USD,
        },
        "medications": medications,
        "totals": totals,
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }

    JSON_OUTPUT_PATH.write_text(json.dumps(analysis, indent=2) + "\n")

    summary_lines = [
        "# Refill Analysis Summary",
        f"Total 90-day annual revenue: ${totals['annual_revenue_90_day_usd']:,.2f}",
        f"Total 100-day annual revenue: ${totals['annual_revenue_100_day_usd']:,.2f}",
        f"Absolute total revenue difference: ${absolute_total_difference:,.2f}",
        f"Decision: {decision}",
        justification,
    ]
    SUMMARY_OUTPUT_PATH.write_text("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

